// Offline shell for the iPhone console. Cache key is generated by build-index.py
// from the index, all precached assets and this worker's implementation.
const CACHE = "mega-mobile-v1-f0a03afbdf7bc464"; // generated by build-index.py
const CACHE_PREFIX = "mega-mobile-";
const ASSETS = [
  "./",
  "./index.html",
  "./styles.css",
  "./app.js",
  "./search.mjs",
  "./manifest.webmanifest",
  "./skills-index.json",
  "./icon.svg",
  "./icon-192.png",
  "./icon-512.png",
  "./apple-touch-icon.png",
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE)
      .then((cache) => cache.addAll(ASSETS))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const cacheNames = await caches.keys();
    // Cache Storage is shared by every app on an origin; never delete another
    // app's cache while cleaning up this console's previous versions.
    await Promise.all(cacheNames
      .filter((name) => name.startsWith(CACHE_PREFIX) && name !== CACHE)
      .map((name) => caches.delete(name)));
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;

  const scope = new URL(self.registration.scope);
  const requestUrl = new URL(request.url);
  if (requestUrl.origin !== scope.origin || !requestUrl.pathname.startsWith(scope.pathname)) return;

  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const cached = await cache.match(request);
    if (cached) return cached;

    try {
      const response = await fetch(request);
      if (response.ok) await cache.put(request, response.clone());
      return response;
    } catch (error) {
      // Only a page navigation may fall back to the app shell. Returning HTML
      // for a failed image/script/API request masks the real offline failure.
      if (request.mode === "navigate") {
        const shell = await cache.match(new URL("./index.html", scope).href);
        if (shell) return shell;
      }
      throw error;
    }
  })());
});
